  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, K, K]");

  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);

  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1 assumed)");
  TORCH_CHECK(w.size(2) == w.size(3), "kernel must be square");
  int64_t K = w.size(2);

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  // Query device shared memory capacity to pick tile size
  int device = 0;
  cudaGetDevice(&device);
  int max_smem_optin = 0;
  cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
  if (max_smem_optin <= 0) {
    max_smem_optin = 48 * 1024; // conservative fallback
  }

  int TILE = 16;
  auto compute_input_bytes = [&](int tile) -> size_t {
    int ih_tile = (tile - 1) * stride + (int)K;
    int iw_tile = (tile - 1) * stride + (int)K;
    return (size_t)Cin * ih_tile * iw_tile * sizeof(float);
  };
  size_t per_channel_weight_bytes = (size_t)Cin * K * K * sizeof(float);
  auto compute_cout_tile = [&](size_t input_bytes) -> int {
    if ((size_t)max_smem_optin <= input_bytes) return 0;
    size_t remaining = (size_t)max_smem_optin - input_bytes;
    int ct = (int)(remaining / per_channel_weight_bytes);
    ct = std::max(0, std::min(ct, (int)Cout));
    return ct;
  };
  size_t input_bytes = compute_input_bytes(TILE);
  int cout_tile = compute_cout_tile(input_bytes);
  if (cout_tile <= 0) {
    TILE = 8;
    input_bytes = compute_input_bytes(TILE);
    cout_tile = compute_cout_tile(input_bytes);
  }
  if (cout_tile <= 0) {
    TILE = 4;
    input_bytes = compute_input_bytes(TILE);
    cout_tile = compute_cout_tile(input_bytes);
  }
  if (cout_tile <= 0) {
    TILE = 2;
    input_bytes = compute_input_bytes(TILE);
    cout_tile = compute_cout_tile(input_bytes);
  }
  TORCH_CHECK(cout_tile > 0,
      "Unable to fit even a single output channel's weights into the shared "
      "memory budget (", max_smem_optin, " bytes) alongside an input tile of ",
      input_bytes, " bytes");
  size_t smem_bytes = input_bytes + (size_t)cout_tile * per_channel_weight_bytes;
  TORCH_CHECK(smem_bytes <= (size_t)max_smem_optin,
      "Computed shared memory ", smem_bytes,
      " still exceeds device limit ", max_smem_optin);
  int IH_tile = (TILE - 1) * stride + (int)K;
  int IW_tile = (TILE - 1) * stride + (int)K;
  auto attr_err = cudaFuncSetAttribute(conv2d_tiled_kernel,
                        cudaFuncAttributeMaxDynamicSharedMemorySize,
                        (int)smem_bytes);
  TORCH_CHECK(attr_err == cudaSuccess,
      "cudaFuncSetAttribute failed for smem_bytes=", smem_bytes,
      " (", cudaGetErrorString(attr_err), ")");
  dim3 block(TILE * TILE);
  dim3 grid(
      (unsigned)((Wout + TILE - 1) / TILE),
      (unsigned)((Hout + TILE - 1) / TILE),
      (unsigned)N
  );
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_tiled_kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)K, stride, padding,
      (int)Hout, (int)Wout,
      TILE, TILE, IH_tile, IW_tile, cout_tile
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
